/// Whether [inputJql] is a GitHub search query rather than Jira JQL.
bool looksLikeGithubQuery(String inputJql) {
  final t = inputJql.toLowerCase();
  const markers = [
    'is:issue',
    'is:pr',
    'repo:',
    'label:',
    'assignee:',
    'state:',
    'type:issue',
  ];
  if (markers.any(t.contains)) return true;
