```dart
String _convertInlinePairs(String s) {
  final buf = StringBuffer();
  var last = 0;
  for (final m in _inlineCodePair.allMatches(s)) {
    final before = s.substring(last, m.start);
    final after = s.substring(m.end);
    final wholeLine = before.trim().isEmpty && after.trim().isEmpty;
    buf.write(_convertText(before));
    final content = m.group(2)!.trim();
    if (wholeLine) {
      buf.write('```${m.group(1) ?? ''}\n$content\n```');
    } else {
      buf.write('`$content`');
    }
    last = m.end;
  }
  buf.write(_convertText(s.substring(last)));
  return buf.toString();
}
```
